Object.assign(SNIP,{});PRESET_NOTES["l71"]={"Ví dụ: Đếm trâu bò": "Có 63 số trong [0, 1000] có tổng chữ số 10. Cách này đúng nhưng với N = 10^18 thì không bao giờ xong.", "Ví dụ: QHĐ chữ số có nhớ": "Cùng đáp án 63 cho N = 1000. Với N = 10^18, bảng nho có 19 × 11 ô, mỗi ô thử 10 chữ số.", "Ví dụ: Không chứa chữ số 4": "[0, 10] bỏ số 4 còn 10 số. [0, 50]: bỏ 4, 14, 24, 34, 40 … 49 còn 37. Đoạn [40, 100] = f(100) − f(39).", "Ví dụ: Đếm trên đoạn [L, R]": "Các số trong [100, 200] có tổng chữ số 5: 104, 113, 122, 131, 140 — 5 số. Một hàm f cho đoạn [0, X] là đủ cho mọi đoạn.", "Lỗi: quên cờ chặt": "In 8: đã đếm mọi số có hai chữ số tới 99 (thêm 34, 43, 52, 61, 70), vượt quá X = 25. Cờ chặt giữ cho số đang dựng không vượt X."};EX_HINTS["l71"]=[["f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(R) − f(L − 1).", "Đi qua từng chữ số c của X: mọi chữ số d < c, d ≠ 4 cho 9^(số vị trí còn lại) số (mỗi vị trí sau có 9 lựa chọn). Rồi giữ chặt bằng cách chọn đúng c — nếu c = 4 thì dừng.", "Nếu đi hết mà không gặp 4 thì cộng 1 cho chính X. Duyệt từng số từ L tới R thì 10^18 bước."], ["Trạng thái: vị trí pos, tổng các chữ số đã chọn, cờ chặt. Tổng vượt S thì cắt nhánh (trả 0).", "Chữ số tiếp theo d chạy từ 0 tới (chặt ? chữ số của X tại pos : 9); cờ chặt mới = chặt && d == giới hạn.", "Chỉ nhớ kết quả khi không chặt: nho[pos][tong]. Đáp án f(R) − f(L − 1)."], ["Trạng thái: vị trí, chữ số vừa chọn (truoc), cờ chặt. Dùng truoc = 10 cho “chưa bắt đầu” (toàn số 0 ở đầu).", "Khi chưa bắt đầu, chọn d = 0 thì vẫn chưa bắt đầu (không bị cấm vì trùng 0 trước đó); chọn d > 0 thì số bắt đầu với chữ số d. Đã bắt đầu thì cấm d = truoc.", "Kết thúc: chỉ tính khi số đã bắt đầu (bỏ số 0). Nhớ nho[pos][truoc] khi không chặt."]];
/* ===================== BÀI 71 · Quy hoạch động chữ số ===================== */
/* Bài 71 · Quy hoạch động chữ số
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR71=[{label:"Ví dụ: Đếm trâu bò",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint tongChuSo(int x) {\n    int s = 0;\n    while (x > 0) { s += x % 10; x /= 10; }\n    return s;\n}\n\nint main() {\n    int N = 1000, S = 10, dem = 0;\n    for (int x = 0; x <= N; x++)       // thử từng số: O(N · số chữ số)\n        if (tongChuSo(x) == S) dem++;\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["x","dem"]}],py:{code:"def tong_chu_so(x):\n    return sum(int(c) for c in str(x))\n\nN, S = 1000, 10\ndem = 0\nfor x in range(N + 1):                 # thử từng số: O(N · số chữ số)\n    if tong_chu_so(x) == S:\n        dem += 1\nprint(dem)"},cs:{code:"using System;\n\nclass Program\n{\n    static int TongChuSo(int x)\n    {\n        int s = 0;\n        while (x > 0) { s += x % 10; x /= 10; }\n        return s;\n    }\n\n    static void Main()\n    {\n        int N = 1000, S = 10, dem = 0;\n        for (int x = 0; x <= N; x++)           // thử từng số: O(N · số chữ số)\n            if (TongChuSo(x) == S) dem++;\n        Console.WriteLine(dem);\n    }\n}"}},{label:"Ví dụ: QHĐ chữ số có nhớ",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring so;                             // X viết thành chuỗi chữ số\nint S;\nvector<vector<long long>> nho;         // nho[pos][tong], -1 = chưa tính\n\nlong long dem(int pos, int tong, bool chat) {\n    if (tong > S) return 0;\n    if (pos == (int)so.size()) return tong == S ? 1 : 0;\n    if (!chat && nho[pos][tong] != -1) return nho[pos][tong];\n    int gh = chat ? so[pos] - '0' : 9; // chặt: không vượt chữ số của X\n    long long kq = 0;\n    for (int d = 0; d <= gh; d++) kq += dem(pos + 1, tong + d, chat && d == gh);\n    if (!chat) nho[pos][tong] = kq;\n    return kq;\n}\n\nlong long f(long long X) {             // số các số trong [0, X] có tổng chữ số S\n    if (X < 0) return 0;\n    so = to_string(X);\n    nho.assign(so.size(), vector<long long>(S + 1, -1));\n    return dem(0, 0, true);\n}\n\nint main() {\n    S = 10;\n    cout << f(1000) << \"\\n\";\n    cout << f(1000000000000000000LL) << \"\\n\";   // 10^18: chỉ vài nghìn trạng thái\n    return 0;\n}",viz:[{type:"vars",names:["so","pos","tong","chat","gh","d"]},{type:"calls"}],py:{code:"def dem(pos, tong, chat):\n    if tong > S:\n        return 0\n    if pos == len(so):\n        return 1 if tong == S else 0\n    if not chat and nho[pos][tong] != -1:\n        return nho[pos][tong]\n    gh = int(so[pos]) if chat else 9   # chặt: không vượt chữ số của X\n    kq = 0\n    for d in range(gh + 1):\n        kq += dem(pos + 1, tong + d, chat and d == gh)\n    if not chat:\n        nho[pos][tong] = kq\n    return kq\n\ndef f(X):                              # số các số trong [0, X] có tổng chữ số S\n    global so, nho\n    if X < 0:\n        return 0\n    so = str(X)\n    nho = [[-1] * (S + 1) for _ in range(len(so))]\n    return dem(0, 0, True)\n\nS = 10\nprint(f(1000))\nprint(f(10 ** 18))                     # 10^18: chỉ vài nghìn trạng thái"},cs:{code:"using System;\n\nclass Program\n{\n    static string so;                      // X viết thành chuỗi chữ số\n    static int S;\n    static long[][] nho;                   // nho[pos][tong], -1 = chưa tính\n\n    static long Dem(int pos, int tong, bool chat)\n    {\n        if (tong > S) return 0;\n        if (pos == so.Length) return tong == S ? 1 : 0;\n        if (!chat && nho[pos][tong] != -1) return nho[pos][tong];\n        int gh = chat ? so[pos] - '0' : 9; // chặt: không vượt chữ số của X\n        long kq = 0;\n        for (int d = 0; d <= gh; d++) kq += Dem(pos + 1, tong + d, chat && d == gh);\n        if (!chat) nho[pos][tong] = kq;\n        return kq;\n    }\n\n    static long F(long X)                  // số các số trong [0, X] có tổng chữ số S\n    {\n        if (X < 0) return 0;\n        so = X.ToString();\n        nho = new long[so.Length][];\n        for (int i = 0; i < so.Length; i++)\n        {\n            nho[i] = new long[S + 1];\n            for (int t = 0; t <= S; t++) nho[i][t] = -1;\n        }\n        return Dem(0, 0, true);\n    }\n\n    static void Main()\n    {\n        S = 10;\n        Console.WriteLine(F(1000));\n        Console.WriteLine(F(1000000000000000000L));   // 10^18: chỉ vài nghìn trạng thái\n    }\n}"}},{label:"Ví dụ: Không chứa chữ số 4",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nlong long khongCo4(long long X) {      // số các số trong [0, X] không có chữ số 4\n    if (X < 0) return 0;\n    string so = to_string(X);\n    int n = so.size();\n    vector<long long> p9(n + 1, 1);    // p9[k] = 9^k: k vị trí tự do, mỗi vị trí 9 lựa chọn\n    for (int k = 1; k <= n; k++) p9[k] = p9[k - 1] * 9;\n    long long kq = 0;\n    for (int pos = 0; pos < n; pos++) {\n        int c = so[pos] - '0';\n        for (int d = 0; d < c; d++)    // chọn d nhỏ hơn: các vị trí sau tự do\n            if (d != 4) kq += p9[n - pos - 1];\n        if (c == 4) return kq;         // muốn giữ chặt thì phải chọn 4: dừng\n    }\n    return kq + 1;                     // chính X không có chữ số 4\n}\n\nint main() {\n    cout << khongCo4(10) << \" \" << khongCo4(50) << \" \" << khongCo4(1000) << \"\\n\";\n    cout << khongCo4(100) - khongCo4(39) << \"\\n\";   // đoạn [40, 100]\n    return 0;\n}",viz:[{type:"vars",names:["so","pos","c","d","kq"]}],py:{code:"def khong_co_4(X):                     # số các số trong [0, X] không có chữ số 4\n    if X < 0:\n        return 0\n    so = str(X)\n    n = len(so)\n    kq = 0\n    for pos in range(n):\n        c = int(so[pos])\n        for d in range(c):             # chọn d nhỏ hơn: các vị trí sau tự do\n            if d != 4:\n                kq += 9 ** (n - pos - 1)\n        if c == 4:                     # muốn giữ chặt thì phải chọn 4: dừng\n            return kq\n    return kq + 1                      # chính X không có chữ số 4\n\nprint(khong_co_4(10), khong_co_4(50), khong_co_4(1000))\nprint(khong_co_4(100) - khong_co_4(39))   # đoạn [40, 100]"},cs:{code:"using System;\n\nclass Program\n{\n    static long KhongCo4(long X)           // số các số trong [0, X] không có chữ số 4\n    {\n        if (X < 0) return 0;\n        string so = X.ToString();\n        int n = so.Length;\n        long[] p9 = new long[n + 1];       // p9[k] = 9^k\n        p9[0] = 1;\n        for (int k = 1; k <= n; k++) p9[k] = p9[k - 1] * 9;\n        long kq = 0;\n        for (int pos = 0; pos < n; pos++)\n        {\n            int c = so[pos] - '0';\n            for (int d = 0; d < c; d++)    // chọn d nhỏ hơn: các vị trí sau tự do\n                if (d != 4) kq += p9[n - pos - 1];\n            if (c == 4) return kq;         // muốn giữ chặt thì phải chọn 4: dừng\n        }\n        return kq + 1;                     // chính X không có chữ số 4\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(KhongCo4(10) + \" \" + KhongCo4(50) + \" \" + KhongCo4(1000));\n        Console.WriteLine(KhongCo4(100) - KhongCo4(39));   // đoạn [40, 100]\n    }\n}"}},{label:"Ví dụ: Đếm trên đoạn [L, R]",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring so;                             // X viết thành chuỗi chữ số\nint S;\nvector<vector<long long>> nho;         // nho[pos][tong], -1 = chưa tính\n\nlong long dem(int pos, int tong, bool chat) {\n    if (tong > S) return 0;\n    if (pos == (int)so.size()) return tong == S ? 1 : 0;\n    if (!chat && nho[pos][tong] != -1) return nho[pos][tong];\n    int gh = chat ? so[pos] - '0' : 9; // chặt: không vượt chữ số của X\n    long long kq = 0;\n    for (int d = 0; d <= gh; d++) kq += dem(pos + 1, tong + d, chat && d == gh);\n    if (!chat) nho[pos][tong] = kq;\n    return kq;\n}\n\nlong long f(long long X) {             // số các số trong [0, X] có tổng chữ số S\n    if (X < 0) return 0;\n    so = to_string(X);\n    nho.assign(so.size(), vector<long long>(S + 1, -1));\n    return dem(0, 0, true);\n}\n\nint main() {\n    S = 5;\n    long long Lo = 100, Hi = 200;\n    cout << f(Hi) - f(Lo - 1) << \"\\n\"; // [100, 200] = [0, 200] bỏ đi [0, 99]\n    return 0;\n}",py:{code:"def dem(pos, tong, chat):\n    if tong > S:\n        return 0\n    if pos == len(so):\n        return 1 if tong == S else 0\n    if not chat and nho[pos][tong] != -1:\n        return nho[pos][tong]\n    gh = int(so[pos]) if chat else 9   # chặt: không vượt chữ số của X\n    kq = 0\n    for d in range(gh + 1):\n        kq += dem(pos + 1, tong + d, chat and d == gh)\n    if not chat:\n        nho[pos][tong] = kq\n    return kq\n\ndef f(X):                              # số các số trong [0, X] có tổng chữ số S\n    global so, nho\n    if X < 0:\n        return 0\n    so = str(X)\n    nho = [[-1] * (S + 1) for _ in range(len(so))]\n    return dem(0, 0, True)\n\nS = 5\nlo, hi = 100, 200\nprint(f(hi) - f(lo - 1))               # [100, 200] = [0, 200] bỏ đi [0, 99]"},cs:{code:"using System;\n\nclass Program\n{\n    static string so;                      // X viết thành chuỗi chữ số\n    static int S;\n    static long[][] nho;                   // nho[pos][tong], -1 = chưa tính\n\n    static long Dem(int pos, int tong, bool chat)\n    {\n        if (tong > S) return 0;\n        if (pos == so.Length) return tong == S ? 1 : 0;\n        if (!chat && nho[pos][tong] != -1) return nho[pos][tong];\n        int gh = chat ? so[pos] - '0' : 9; // chặt: không vượt chữ số của X\n        long kq = 0;\n        for (int d = 0; d <= gh; d++) kq += Dem(pos + 1, tong + d, chat && d == gh);\n        if (!chat) nho[pos][tong] = kq;\n        return kq;\n    }\n\n    static long F(long X)                  // số các số trong [0, X] có tổng chữ số S\n    {\n        if (X < 0) return 0;\n        so = X.ToString();\n        nho = new long[so.Length][];\n        for (int i = 0; i < so.Length; i++)\n        {\n            nho[i] = new long[S + 1];\n            for (int t = 0; t <= S; t++) nho[i][t] = -1;\n        }\n        return Dem(0, 0, true);\n    }\n\n    static void Main()\n    {\n        S = 5;\n        long lo = 100, hi = 200;\n        Console.WriteLine(F(hi) - F(lo - 1));  // [100, 200] = [0, 200] bỏ đi [0, 99]\n    }\n}"}},{label:"Lỗi: quên cờ chặt",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring so;\nint S;\n\nlong long dem(int pos, int tong) {     // SAI: không có cờ chặt, mọi vị trí đều 0..9\n    if (pos == (int)so.size()) return tong == S ? 1 : 0;\n    long long kq = 0;\n    for (int d = 0; d <= 9; d++) kq += dem(pos + 1, tong + d);\n    return kq;\n}\n\nint main() {\n    so = \"25\";\n    S = 7;\n    cout << dem(0, 0) << \"\\n\";         // đúng phải là 3 (7, 16, 25)\n    return 0;\n}",viz:[{type:"vars",names:["pos","tong","d","kq"]},{type:"calls"}],py:{code:"def dem(pos, tong):                    # SAI: không có cờ chặt, mọi vị trí đều 0..9\n    if pos == len(so):\n        return 1 if tong == S else 0\n    kq = 0\n    for d in range(10):\n        kq += dem(pos + 1, tong + d)\n    return kq\n\nso = \"25\"\nS = 7\nprint(dem(0, 0))                       # đúng phải là 3 (7, 16, 25)"},cs:{code:"using System;\n\nclass Program\n{\n    static string so;\n    static int S;\n\n    static long Dem(int pos, int tong)     // SAI: không có cờ chặt, mọi vị trí đều 0..9\n    {\n        if (pos == so.Length) return tong == S ? 1 : 0;\n        long kq = 0;\n        for (int d = 0; d <= 9; d++) kq += Dem(pos + 1, tong + d);\n        return kq;\n    }\n\n    static void Main()\n    {\n        so = \"25\";\n        S = 7;\n        Console.WriteLine(Dem(0, 0));          // đúng phải là 3 (7, 16, 25)\n    }\n}"}}];
