makeEx2(document.getElementById("ex-l71"),sim71,[{t:"Tòa nhà kiêng số 4",d:"Một tòa nhà bỏ mọi số phòng có chứa chữ số 4. Cho L, R (1 ≤ L ≤ R ≤ 10^18), đếm số số nguyên trong [L, R] không chứa chữ số 4. Đầu vào: một dòng L R. Đầu ra: một số.",tests:[{in:"1 10",out:"9"},{in:"1 50",out:"36"},{in:"40 49",out:"0"},{in:"1 1000000000000000000",out:"150094635296999121"},{in:"123456789 987654321",out:"326924424"},{in:"4 4",out:"0"},{in:"5 5",out:"1"},{in:"559736258522 38181571375714008",out:"7041254920524475"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    long long Lo, Hi;\n    cin >> Lo >> Hi;\n    // f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(Hi) − f(Lo − 1)\n    cout << 0 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"1 "+(n*100),ns:[250,500,1000,2000],need:"n",limit:n=>20*n+20000,why:"Duyệt từng số trong đoạn tốn O(R − L) — tới 10^18."},py:{start:"lo, hi = map(int, input().split())\n# f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(hi) − f(lo − 1)\nprint(0)",hints:["f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(R) − f(L − 1).","Đi qua từng chữ số c của X: mọi chữ số d < c, d ≠ 4 cho 9^(số vị trí còn lại) số. Rồi giữ chặt bằng cách chọn đúng c — nếu c = 4 thì dừng.","Nếu đi hết mà không gặp 4 thì cộng 1 cho chính X. Duyệt từng số từ L tới R thì 10^18 bước."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] c = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        // f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(c[1]) − f(c[0] − 1)\n        Console.WriteLine(0);\n    }\n}",hints:["f(X) = số các số trong [0, X] không có chữ số 4; đáp án f(R) − f(L − 1).","Đi qua từng chữ số c của X: mọi chữ số d < c, d ≠ 4 cho 9^(số vị trí còn lại) số. Rồi giữ chặt bằng cách chọn đúng c — nếu c = 4 thì dừng.","Nếu đi hết mà không gặp 4 thì cộng 1 cho chính X. Duyệt từng số từ L tới R thì 10^18 bước."]}},{t:"Tổng chữ số",d:"Đếm số số nguyên trong [L, R] có tổng các chữ số bằng S. Đầu vào: một dòng L R S (1 ≤ L ≤ R ≤ 10^18, 1 ≤ S ≤ 162). Đầu ra: một số.",tests:[{in:"1 1000 10",out:"63"},{in:"100 200 5",out:"5"},{in:"1 9 9",out:"1"},{in:"1 1000000000000000000 1",out:"19"},{in:"1 1000000000000000000 81",out:"32458256583753952"},{in:"999 999 27",out:"1"},{in:"1 1000000000000000000 162",out:"1"},{in:"166199616 872372256793412828 26",out:"399012829862"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring so;\nint S;\nvector<vector<long long>> nho;\n\nlong long dem(int pos, int tong, bool chat) {\n    // QHĐ chữ số: thử chữ số d từ 0 tới (chat ? so[pos] : 9)\n    return 0;\n}\n\nlong long f(long long X) {\n    if (X < 0) return 0;\n    so = to_string(X);\n    nho.assign(so.size(), vector<long long>(S + 1, -1));\n    return dem(0, 0, true);\n}\n\nint main() {\n    long long Lo, Hi;\n    cin >> Lo >> Hi >> S;\n    cout << f(Hi) - f(Lo - 1) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"1 "+(n*100)+" 10",ns:[250,500,1000,2000],need:"n",limit:n=>20*n+60000,why:"Duyệt từng số trong đoạn tốn O(R − L) — tới 10^18."},py:{start:"def dem(pos, tong, chat):\n    # QHĐ chữ số: thử chữ số d từ 0 tới (int(so[pos]) nếu chat, không thì 9)\n    return 0\n\ndef f(X):\n    global so, nho\n    if X < 0:\n        return 0\n    so = str(X)\n    nho = [[-1] * (S + 1) for _ in range(len(so))]\n    return dem(0, 0, True)\n\nlo, hi, S = map(int, input().split())\nprint(f(hi) - f(lo - 1))",hints:["Trạng thái: vị trí pos, tổng các chữ số đã chọn, cờ chặt. Tổng vượt S thì cắt nhánh.","Chữ số tiếp theo d chạy từ 0 tới (chặt ? chữ số của X tại pos : 9); cờ chặt mới = chat and d == gh.","Chỉ nhớ khi không chặt: nho[pos][tong]. (Hoặc dùng functools.lru_cache, nhớ xóa cache giữa hai lần gọi f.)"]},cs:{start:"using System;\n\nclass Program\n{\n    static string so;                      // X viết thành chuỗi chữ số\n    static int S;\n    static long[][] nho;                   // nho[pos][tong], -1 = chưa tính\n\n    static long Dem(int pos, int tong, bool chat)\n    {\n        // QHĐ chữ số: thử chữ số d từ 0 tới (chat ? so[pos] - '0' : 9)\n        return 0;\n    }\n\n    static long F(long X)                  // số các số trong [0, X] có tổng chữ số S\n    {\n        if (X < 0) return 0;\n        so = X.ToString();\n        nho = new long[so.Length][];\n        for (int i = 0; i < so.Length; i++)\n        {\n            nho[i] = new long[S + 1];\n            for (int t = 0; t <= S; t++) nho[i][t] = -1;\n        }\n        return Dem(0, 0, true);\n    }\n\n    static void Main()\n    {\n        long[] c = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        S = (int)c[2];\n        Console.WriteLine(F(c[1]) - F(c[0] - 1));\n    }\n}",hints:["Trạng thái: vị trí pos, tổng các chữ số đã chọn, cờ chặt. Tổng vượt S thì cắt nhánh.","Chữ số tiếp theo d chạy từ 0 tới (chặt ? so[pos] − '0' : 9); cờ chặt mới = chat && d == gh.","Chỉ nhớ khi không chặt: nho[pos][tong]. Đáp án F(R) − F(L − 1)."]}},{t:"Số hiệu lấp lánh",d:"Một số nguyên dương gọi là “lấp lánh” nếu hai chữ số kề nhau bất kỳ luôn khác nhau (ví dụ 1, 121, 9090 lấp lánh; 11, 1223 thì không). Đếm số số lấp lánh trong [1, N]. Đầu vào: N (1 ≤ N ≤ 10^18). Đầu ra: một số.",tests:[{in:"10",out:"10"},{in:"100",out:"90"},{in:"1",out:"1"},{in:"11",out:"10"},{in:"1000",out:"819"},{in:"9090",out:"6724"},{in:"1000000000000000000",out:"168856464709124010"},{in:"12501157691183347",out:"2382077395432422"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring so;\nvector<vector<long long>> nho;         // nho[pos][truoc], truoc = 10 nghĩa là chưa bắt đầu số\n\nlong long dem(int pos, int truoc, bool chat) {\n    // số 0 ở đầu: khi truoc = 10 và chọn d = 0, số vẫn chưa bắt đầu\n    return 0;\n}\n\nint main() {\n    long long N;\n    cin >> N;\n    so = to_string(N);\n    nho.assign(so.size(), vector<long long>(11, -1));\n    cout << dem(0, 10, true) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>String(n*100),ns:[250,500,1000,2000],need:"n",limit:n=>20*n+60000,why:"Kiểm tra từng số từ 1 tới N tốn O(N) — tới 10^18."},py:{start:"N = int(input())\nso = str(N)\nnho = [[-1] * 11 for _ in range(len(so))]   # nho[pos][truoc], truoc = 10: chưa bắt đầu số\n\ndef dem(pos, truoc, chat):\n    # số 0 ở đầu: khi truoc = 10 và chọn d = 0, số vẫn chưa bắt đầu\n    return 0\n\nprint(dem(0, 10, True))",hints:["Trạng thái: vị trí, chữ số vừa chọn (truoc), cờ chặt. Dùng truoc = 10 cho “chưa bắt đầu”.","Chưa bắt đầu mà chọn d = 0 thì vẫn chưa bắt đầu; chọn d > 0 thì số bắt đầu. Đã bắt đầu thì cấm d = truoc.","Kết thúc: chỉ tính khi số đã bắt đầu (bỏ số 0). Nhớ nho[pos][truoc] khi không chặt."]},cs:{start:"using System;\n\nclass Program\n{\n    static string so;\n    static long[][] nho;                   // nho[pos][truoc], truoc = 10: chưa bắt đầu số\n\n    static long Dem(int pos, int truoc, bool chat)\n    {\n        // số 0 ở đầu: khi truoc = 10 và chọn d = 0, số vẫn chưa bắt đầu\n        return 0;\n    }\n\n    static void Main()\n    {\n        long N = long.Parse(Console.ReadLine());\n        so = N.ToString();\n        nho = new long[so.Length][];\n        for (int i = 0; i < so.Length; i++)\n        {\n            nho[i] = new long[11];\n            for (int t = 0; t <= 10; t++) nho[i][t] = -1;\n        }\n        Console.WriteLine(Dem(0, 10, true));\n    }\n}",hints:["Trạng thái: vị trí, chữ số vừa chọn (truoc), cờ chặt. Dùng truoc = 10 cho “chưa bắt đầu”.","Chưa bắt đầu mà chọn d = 0 thì vẫn chưa bắt đầu; chọn d > 0 thì số bắt đầu. Đã bắt đầu thì cấm d = truoc.","Kết thúc: chỉ tính khi số đã bắt đầu (bỏ số 0). Nhớ nho[pos][truoc] khi không chặt."]}}]);

makeQuiz("quiz71","score71",[{"q": "Để đếm trên [L, R], ta thường tính?", "o": ["f(R) + f(L)", "f(R) − f(L − 1) với f(X) đếm trên [0, X]", "f(R − L)", "f(R) − f(L)"], "a": 1, "e": "Một hàm f đủ cho mọi đoạn."}, {"q": "Cờ “chặt” cho biết gì?", "o": ["Số đang dựng đã lớn hơn X", "Các chữ số đã chọn trùng hệt tiền tố của X nên chữ số tiếp theo bị giới hạn", "Đã chọn hết chữ số", "Tổng chữ số vượt S"], "a": 1, "e": "Chọn một chữ số nhỏ hơn là hết chặt."}, {"q": "Vì sao chỉ ghi nhớ kết quả khi không chặt?", "o": ["Vì trạng thái chặt chỉ xuất hiện trên đúng một đường, và phụ thuộc chữ số của X", "Vì bộ nhớ không đủ", "Vì kết quả chặt luôn bằng 0", "Không cần lý do"], "a": 0, "e": "Kết quả không chặt dùng lại được cho mọi nhánh."}, {"q": "Với tính chất “hai chữ số kề nhau khác nhau”, vì sao cần trạng thái “chưa bắt đầu”?", "o": ["Để tính nhanh hơn", "Vì số 0 ở đầu (như 007) không phải chữ số thật, không được coi là kề với chữ số đầu tiên", "Vì C++ yêu cầu", "Không cần"], "a": 1, "e": "007 là số 7 — vẫn lấp lánh."}]);

